  // Multiply out every subarray exactly with BigInt and take the remainder at the end.
  const result = new Array(k).fill(0);
  for (let left = 0; left < nums.length; left++) {
    for (let right = left; right < nums.length; right++) {
      let product = 1n;
      for (let i = left; i <= right; i++) product *= BigInt(nums[i]);
      result[Number(product % BigInt(k))]++;
    }
