function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? 2000 : pick(1, 10);
  const style = rand();
  const nums = [];
  for (let i = 0; i < n; i++) {
    if (style < 0.4) nums.push(pick(1, 12));
    else if (style < 0.6) nums.push(pick(1, 3));
    else nums.push(pick(1, 1000000000));
  }
  return [nums, pick(1, 5)];
}
